{
  "name": "串行控制组件",
  "name_en": "Serial Controller Component",
  "manufacturer": "Donkeycar",
  "description": "这是一个非物理的软件控制组件，用于在 Donkeycar 风格的流程中通过串行通信链路更新并提供控制信号。根据现有证据，它主要围绕转向角和油门等信号进行运行、轮询或线程化读取，适合用于实验小车控制流程中的信号传递与集成。",
  "description_en": "This is a non-physical software control component used in a Donkeycar-style workflow to update and provide control signals over a serial communication link. Based on the available evidence, it mainly handles run-loop, polling, or threaded access to signals such as steering angle and throttle, for integration within an experimental vehicle control pipeline.",
  "actions": [
    {
      "action_name": "auto-update",
      "description": "更新串行控制状态。",
      "description_en": "Update the serial control state."
    },
    {
      "action_name": "auto-run",
      "description": "运行一次串行控制处理并输出当前控制信号。",
      "description_en": "Run one serial control cycle and output the current control signals."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "在线程模式下运行串行控制并获取当前控制信号。",
      "description_en": "Run the serial control component in threaded mode and obtain the current control signals."
    }
  ],
  "tag_hints": [
    "serial control",
    "Donkeycar",
    "steering and throttle signals",
    "vehicle control pipeline",
    "threaded update loop"
  ]
}

